-- This statement defines the SCHEMA (structure)
CREATE TABLE student (
  roll_no   INT PRIMARY KEY,
  name      VARCHAR(50) NOT NULL,
  city      VARCHAR(30)
);

-- This statement changes the INSTANCE (data)
INSERT INTO student VALUES (101, 'Asha Patel', 'Vadodara');

CREATE TABLE student (
  roll_no INT PRIMARY KEY,
  name    VARCHAR(50) NOT NULL
);

CREATE TABLE book (
  book_id INT PRIMARY KEY,
  title   VARCHAR(100) NOT NULL
);

-- M:N relationship becomes its own table
CREATE TABLE borrow (
  roll_no   INT,
  book_id   INT,
  issue_date DATE,
  PRIMARY KEY (roll_no, book_id, issue_date),
  FOREIGN KEY (roll_no) REFERENCES student(roll_no),
  FOREIGN KEY (book_id) REFERENCES book(book_id)
);

