VALUES (105, 'Divya', 'Rajkot', 2);

UPDATE student SET city = 'Ahmedabad' WHERE roll_no = 102;

DELETE FROM student WHERE roll_no = 104;

START TRANSACTION;

UPDATE account SET balance = balance - 500 WHERE acc_no = 'A101';
UPDATE account SET balance = balance + 500 WHERE acc_no = 'R202';

COMMIT;      -- make both changes permanent
-- ROLLBACK; -- or undo both if something went wrong

-- Speed up lookups by phone number
CREATE INDEX idx_customer_phone ON customer(phone);

-- See how the database plans to run a query
EXPLAIN SELECT * FROM customer WHERE phone = '9825000001';

-- Remove an index that is not useful
DROP INDEX idx_customer_phone ON customer;

-- Give a reporting user read-only access to one table
CREATE USER report_user IDENTIFIED BY 'use-a-long-random-password';
GRANT SELECT ON college.student TO report_user;

-- Remove a privilege that is no longer needed
REVOKE SELECT ON college.student FROM report_user;
